你触碰一名自愿生物或者一个未被着装或携带的物件以在其上设置一道幻术。生物获得下述伪装效应，物件则获得下述虚假灵光效应。效应持续至法术结束。如果你持续30日每日均对同一个目标施展此法术，则幻术会的持续时间变为直至被解除。
伪装Mask（生物）。选择一种目标实际生物类型以外的生物类别。法术和其他魔法效应会将目标生物视为属于该生物类型来处理效果。
虚假灵光False
