你唤来一个天界灵魄。其使用下文天界灵魄的数据，并会在施法距离内一处你可见的未占据空间中显现。当你施展法术时，从复仇圣灵或守护圣灵选择一个，其数据中的部分特性也受此影响。该生物会在生命值降为0或是法术结束时消失。
该生物是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你回合结束后立即行动。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并用移动力远离危险。
升环施法。该生物的数据使用新的法术环阶。
